/**
 * The contract `tabs.tsx` (native) and `tabs.web.tsx` (radix) both implement.
 * Its own module because Metro resolves `./tabs` to `tabs.web.tsx` on web.
 *
 * Controlled (`value` + `onValueChange`) or uncontrolled (`defaultValue`), as
 * radix is. The web half also takes radix's own props on top of this —
 * `orientation`, `activationMode`, `forceMount`, `dir`, DOM attributes — as
 * shadcn's `tabs` does; those extras are web only.
 */
import type { ReactNode } from "react";
import type { SlotNode } from "@/lib/utils";

export type TabsProps = {
  /** The active tab, when the caller owns it. */
  value?: string | undefined;
  /** Called with the tab the user picked. */
  onValueChange?: ((value: string) => void) | undefined;
  /** The tab active at mount, when uncontrolled. */
  defaultValue?: string | undefined;
  className?: string | undefined;
  children: ReactNode;
};

export type TabsListProps = {
  /**
   * The tablist's name, read on entering it: "Project view, tab list". Give one
   * whenever no visible heading names the tabs — ARIA's tabs pattern asks for it.
   */
  "aria-label"?: string | undefined;
  /** The id of a visible heading that names the tablist, in place of `aria-label`. */
  "aria-labelledby"?: string | undefined;
  /**
   * On the list's box. A list wider than the space it is given scrolls sideways, and brings the
   * selected tab into view, so a row of seven tabs needs nothing here to fit a phone.
   */
  className?: string | undefined;
  children: ReactNode;
};

export type TabsTriggerProps = {
  value: string;
  /** Not selectable, and dimmed. */
  disabled?: boolean | undefined;
  className?: string | undefined;
  /**
   * The label, and optionally an icon beside it: `<Clock /> Recent`. The icon
   * takes the tab's active or inactive colour on both halves.
   */
  children: ReactNode;
  /**
   * The far end of the tab, after its label: a dot for unsaved changes or a server in error, a
   * count. What it says is part of the tab's name, so a dot is `<Badge variant="warning"
   * label="Unsaved changes" />`, which is read as "Device, Unsaved changes", and not a bare
   * coloured view, which is read as nothing.
   */
  trailingSlot?: SlotNode | undefined;
};

export type TabsContentProps = {
  value: string;
  className?: string | undefined;
  children: ReactNode;
};

/**
 * The list's box. How its tabs are centred is each half's own: a list too narrow for its tabs
 * scrolls sideways, and the two platforms centre a row that can overflow differently.
 */
export const TABS_LIST_CLASS =
  "h-10 items-center rounded-md border border-foreground/15 bg-background p-1";
/** The list's own `p-1`, kept clear of a tab brought into view so it does not sit on the border. */
export const TABS_LIST_INSET = 4;
/** A row, so an icon sits beside the label. `gap-1.5` is shadcn's own. */
export const TABS_TRIGGER_CLASS =
  "flex-row items-center justify-center gap-1.5 rounded-sm px-3 py-1.5";
export const TABS_TRIGGER_TEXT_CLASS = "text-sm font-medium";

/**
 * The native tabs: a row of `Pressable`s over a context holding the active
 * value, and content panes that render only when selected.
 *
 * The active value is the caller's `value` when given, and this component's
 * own state otherwise (see `tabs-base.ts`). Unselected panes unmount, as they
 * do under radix without `forceMount`.
 */

import {
  Children,
  createContext,
  type ReactNode,
  useContext,
  useEffect,
  useRef,
  useState,
} from "react";
import { Pressable, ScrollView, Text, View } from "react-native";
import { IconClassContext } from "@/components/ui/icons-base";
import {
  TABS_LIST_CLASS,
  TABS_LIST_INSET,
  TABS_TRIGGER_CLASS,
  TABS_TRIGGER_TEXT_CLASS,
  type TabsContentProps,
  type TabsListProps,
  type TabsProps,
  type TabsTriggerProps,
} from "@/components/ui/tabs-base";
import { cn } from "@/lib/utils";

type TabsState = { value: string; setValue: (value: string) => void };

const TabsContext = createContext<TabsState>({ value: "", setValue: () => {} });

function Tabs({ value: controlled, onValueChange, defaultValue, className, children }: TabsProps) {
  const [uncontrolled, setUncontrolled] = useState(defaultValue ?? "");
  const value = controlled ?? uncontrolled;
  const setValue = (next: string) => {
    if (controlled === undefined) setUncontrolled(next);
    onValueChange?.(next);
  };
  return (
    <TabsContext.Provider value={{ value, setValue }}>
      <View className={cn(className)}>{children}</View>
    </TabsContext.Provider>
  );
}

/** Where a tab sits in the row: its near edge and its width. */
type Span = { x: number; width: number };

/** How a trigger tells its list where the selected tab is, so the list can bring it into view. */
const TabsListContext = createContext<(tab: Span) => void>(() => {});

function TabsList({
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  className,
  children,
}: TabsListProps) {
  const scroller = useRef<ScrollView>(null);
  // Refs, not state: none of the three is drawn, and a scroll would otherwise render the row.
  const viewport = useRef(0);
  const offset = useRef(0);
  const selected = useRef<Span | undefined>(undefined);

  const reveal = () => {
    const tab = selected.current;
    // The triggers can be laid out before the scroller is; it calls back when it has a width.
    if (!tab || viewport.current === 0) return;
    const end = tab.x + tab.width;
    if (tab.x < offset.current) {
      scroller.current?.scrollTo({ x: Math.max(0, tab.x - TABS_LIST_INSET) });
    } else if (end > offset.current + viewport.current) {
      scroller.current?.scrollTo({ x: end - viewport.current + TABS_LIST_INSET });
    }
  };

  // A `tab` outside a `tablist` is an orphan to a screen reader, and axe says so. The role is on
  // the box rather than the scroller inside it, so the scrolling is part of the tablist.
  return (
    <View
      role="tablist"
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledBy}
      className={cn("max-w-full flex-row", TABS_LIST_CLASS, className)}
    >
      <ScrollView
        ref={scroller}
        horizontal
        showsHorizontalScrollIndicator={false}
        onLayout={(event) => {
          viewport.current = event.nativeEvent.layout.width;
          reveal();
        }}
        onScroll={(event) => {
          offset.current = event.nativeEvent.contentOffset.x;
        }}
        scrollEventThrottle={16}
        className="shrink grow"
        // `grow` so tabs that fit are centred in the list, as they were before it scrolled.
        contentContainerClassName="grow flex-row items-center justify-center"
      >
        <TabsListContext.Provider
          value={(tab) => {
            selected.current = tab;
            reveal();
          }}
        >
          {children}
        </TabsListContext.Provider>
      </ScrollView>
    </View>
  );
}

/**
 * A trigger's children with each run of strings and numbers in one `<Text>`,
 * and anything else (an icon, a badge) beside it in the row. An SVG is not
 * valid inside a `<Text>` on device, and a run is kept whole so `{count} open`
 * stays one label rather than two pieces spaced apart by the row's gap.
 */
function label(children: ReactNode, className: string): ReactNode[] {
  const parts: ReactNode[] = [];
  let run: (string | number)[] = [];
  const flush = () => {
    if (run.length === 0) return;
    parts.push(
      <Text key={`text-${parts.length}`} className={className}>
        {run.join("")}
      </Text>,
    );
    run = [];
  };
  for (const child of Children.toArray(children)) {
    if (typeof child === "string" || typeof child === "number") run.push(child);
    else {
      flush();
      parts.push(child);
    }
  }
  flush();
  return parts;
}

function TabsTrigger({
  value,
  disabled = false,
  className,
  children,
  trailingSlot,
}: TabsTriggerProps) {
  const tabs = useContext(TabsContext);
  const reveal = useContext(TabsListContext);
  const span = useRef<Span | undefined>(undefined);
  const active = tabs.value === value;
  const color = active ? "text-active-foreground" : "text-foreground/60";

  // Chosen from somewhere other than a press — a link, the caller's own state — the tab may be
  // off the end of the row. `reveal` is the list's, new every render, and not what this follows.
  // biome-ignore lint/correctness/useExhaustiveDependencies: runs when the tab becomes active
  useEffect(() => {
    if (active && span.current) reveal(span.current);
  }, [active]);

  return (
    <Pressable
      role="tab"
      onLayout={(event) => {
        const { x, width } = event.nativeEvent.layout;
        span.current = { x, width };
        if (active) reveal(span.current);
      }}
      aria-selected={active}
      aria-disabled={disabled}
      disabled={disabled}
      onPress={() => tabs.setValue(value)}
      className={cn(
        TABS_TRIGGER_CLASS,
        active ? "bg-active" : "hover:bg-hover",
        disabled && "opacity-50",
        className,
      )}
    >
      {/* Text colour does not inherit on native, so the active/inactive split
          lands on each `<Text>` and, through the context, on each icon — the
          container's colour reaches neither. */}
      <IconClassContext.Provider value={cn("size-4 shrink-0", color)}>
        {label(children, cn(TABS_TRIGGER_TEXT_CLASS, color))}
        {trailingSlot}
      </IconClassContext.Provider>
    </Pressable>
  );
}

function TabsContent({ value, className, children }: TabsContentProps) {
  const tabs = useContext(TabsContext);
  if (tabs.value !== value) return null;
  return <View className={cn("mt-2", className)}>{children}</View>;
}

export { Tabs, TabsContent, TabsList, TabsTrigger };

/**
 * The web tabs: radix. `tabs.tsx` is the native counterpart and `tabs-base.ts`
 * holds the contract they share.
 *
 * Every part also takes the props of the radix part it renders, as shadcn's
 * `tabs` does, so a DOM call site ports unchanged.
 */

import { Tabs as TabsPrimitive } from "radix-ui";
import type * as React from "react";
import { useEffect, useRef } from "react";
import {
  TABS_LIST_CLASS,
  TABS_LIST_INSET,
  TABS_TRIGGER_CLASS,
  TABS_TRIGGER_TEXT_CLASS,
  type TabsContentProps,
  type TabsListProps,
  type TabsProps,
  type TabsTriggerProps,
} from "@/components/ui/tabs-base";
import { cn } from "@/lib/utils";

/** The shared contract, widened to what the radix part underneath accepts. */
type Wide<Base, Radix> = Base & Omit<Radix, keyof Base>;

function Tabs({
  value,
  onValueChange,
  defaultValue,
  className,
  ...props
}: Wide<TabsProps, React.ComponentProps<typeof TabsPrimitive.Root>>) {
  // Spread only when given, so an absent `value` leaves radix uncontrolled.
  return (
    <TabsPrimitive.Root
      data-slot="tabs"
      className={cn(className)}
      {...props}
      {...(value === undefined ? {} : { value })}
      {...(onValueChange === undefined ? {} : { onValueChange })}
      {...(defaultValue === undefined ? {} : { defaultValue })}
    />
  );
}

/**
 * Scrolls the list so its selected tab is inside it.
 *
 * Not `scrollIntoView`, which also moves every scroller above the list: a page opened on its last
 * tab would jump down to its tabs.
 */
function reveal(list: HTMLElement) {
  const tab = list.querySelector('[role="tab"][data-state="active"]');
  if (!tab) return;
  const box = list.getBoundingClientRect();
  const span = tab.getBoundingClientRect();
  if (span.left < box.left) list.scrollLeft -= box.left - span.left + TABS_LIST_INSET;
  else if (span.right > box.right) list.scrollLeft += span.right - box.right + TABS_LIST_INSET;
}

function TabsList({
  className,
  ref,
  ...props
}: Wide<TabsListProps, React.ComponentProps<typeof TabsPrimitive.List>>) {
  const list = useRef<HTMLDivElement | null>(null);

  // Radix owns which tab is selected and says so only in `data-state`, so that attribute is what
  // is watched: it covers a click, an arrow key, the caller's `value` and a `defaultValue` alike.
  useEffect(() => {
    const node = list.current;
    if (!node) return;
    reveal(node);
    const observer = new MutationObserver(() => reveal(node));
    observer.observe(node, { attributes: true, attributeFilter: ["data-state"], subtree: true });
    return () => observer.disconnect();
  }, []);

  return (
    <TabsPrimitive.List
      data-slot="tabs-list"
      ref={(node) => {
        list.current = node;
        if (typeof ref === "function") return ref(node);
        if (ref) ref.current = node;
      }}
      // `justify-center-safe`: plain centring puts the first tabs of a row that overflows past
      // the start, where no scrolling reaches them. The scrollbar is hidden because the row is
      // 40px tall and the tabs themselves, by arrow key or by drag, are how it moves.
      className={cn(
        "inline-flex max-w-full justify-center-safe overflow-x-auto overflow-y-hidden text-foreground/60 [scrollbar-width:none]",
        TABS_LIST_CLASS,
        className,
      )}
      {...props}
    />
  );
}

function TabsTrigger({
  className,
  disabled,
  children,
  trailingSlot,
  ...props
}: Wide<TabsTriggerProps, React.ComponentProps<typeof TabsPrimitive.Trigger>>) {
  return (
    <TabsPrimitive.Trigger
      data-slot="tabs-trigger"
      {...(disabled === undefined ? {} : { disabled })}
      // An icon child takes the trigger's colour through `currentColor`, so only
      // its size is set here; device has no inheritance and uses a context.
      className={cn(
        "[&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        "inline-flex shrink-0 whitespace-nowrap transition-all focus-visible:outline-none disabled:pointer-events-none disabled:opacity-50 text-foreground/60 hover:bg-hover hover:text-foreground data-[state=inactive]:focus-visible:bg-hover data-[state=inactive]:focus-visible:text-foreground data-[state=active]:focus-visible:bg-active/90 data-[state=active]:bg-active data-[state=active]:text-active-foreground",
        TABS_TRIGGER_CLASS,
        TABS_TRIGGER_TEXT_CLASS,
        className,
      )}
      {...props}
    >
      {children}
      {trailingSlot}
    </TabsPrimitive.Trigger>
  );
}

function TabsContent({
  className,
  ...props
}: Wide<TabsContentProps, React.ComponentProps<typeof TabsPrimitive.Content>>) {
  return (
    <TabsPrimitive.Content
      data-slot="tabs-content"
      className={cn("mt-2 focus-visible:outline-none", className)}
      {...props}
    />
  );
}

export { Tabs, TabsContent, TabsList, TabsTrigger };
